import{_ as e,o as a,c as d,a2 as i}from"./chunks/framework.Cm6XCzck.js";const u=JSON.parse('{"title":"4. Executed Test Baseline","description":"","frontmatter":{},"headers":[],"relativePath":"en/publications/implementation-case-i1.0/part-02.md","filePath":"en/publications/implementation-case-i1.0/part-02.md","lastUpdated":1786439037000}'),r={name:"en/publications/implementation-case-i1.0/part-02.md"};function n(s,t,l,o,c,h){return a(),d("div",null,[...t[0]||(t[0]=[i(`<h1 id="_4-executed-test-baseline" tabindex="-1">4. Executed Test Baseline <a class="header-anchor" href="#_4-executed-test-baseline" aria-label="Permalink to &quot;4. Executed Test Baseline&quot;">​</a></h1><p>The formal product command was <code>npm run test:tmpa:s1.0</code>. It executed the CodeFlowMu product Reader against the fixed bundle and produced the following aggregate:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TMPA Core: S1.0</span></span>
<span class="line"><span>Implementation: CodeFlowMu V1.8.0</span></span>
<span class="line"><span>Product Reader called: true</span></span>
<span class="line"><span>Reference Reader called: false</span></span>
<span class="line"><span>PASS: 14</span></span>
<span class="line"><span>PARTIAL: 0</span></span>
<span class="line"><span>NOT RUN: 0</span></span>
<span class="line"><span>FAIL: 0</span></span>
<span class="line"><span>Aggregate: PASS</span></span></code></pre></div><p>The S1.0 Reference Reader separately reports 14/14 PASS. Its result validates the author-produced reference path; it is not counted as a CodeFlowMu product result.</p><h1 id="_5-c01–c14-product-results" tabindex="-1">5. C01–C14 Product Results <a class="header-anchor" href="#_5-c01–c14-product-results" aria-label="Permalink to &quot;5. C01–C14 Product Results&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Criterion</th><th>Tested behavior</th><th style="text-align:right;">Mandatory assertions</th><th style="text-align:right;">Result</th></tr></thead><tbody><tr><td>C01</td><td>Schema validation and rejection of invalid shapes</td><td style="text-align:right;">3</td><td style="text-align:right;">PASS</td></tr><tr><td>C02</td><td>Primary-carrier and single-writer immutability</td><td style="text-align:right;">5</td><td style="text-align:right;">PASS</td></tr><tr><td>C03</td><td>Duplicate identity handling with source provenance</td><td style="text-align:right;">5</td><td style="text-align:right;">PASS</td></tr><tr><td>C04</td><td>Per-stream continuity and asynchronous progress</td><td style="text-align:right;">4</td><td style="text-align:right;">PASS</td></tr><tr><td>C05</td><td>Role authority evaluation</td><td style="text-align:right;">5</td><td style="text-align:right;">PASS</td></tr><tr><td>C06</td><td>Lifecycle legality and state preservation</td><td style="text-align:right;">9</td><td style="text-align:right;">PASS</td></tr><tr><td>C07</td><td>Separation of duties and human approval authorization</td><td style="text-align:right;">10</td><td style="text-align:right;">PASS</td></tr><tr><td>C08</td><td>Integrity tampering detection</td><td style="text-align:right;">3</td><td style="text-align:right;">PASS</td></tr><tr><td>C09</td><td>Missing-reference treatment</td><td style="text-align:right;">4</td><td style="text-align:right;">PASS</td></tr><tr><td>C10</td><td>Prohibited-cycle detection</td><td style="text-align:right;">4</td><td style="text-align:right;">PASS</td></tr><tr><td>C11</td><td>Aggregation and reconstruction determinism</td><td style="text-align:right;">4</td><td style="text-align:right;">PASS</td></tr><tr><td>C12</td><td>Conflict preservation and explicit resolution</td><td style="text-align:right;">5</td><td style="text-align:right;">PASS</td></tr><tr><td>C13</td><td>Recovery behavior</td><td style="text-align:right;">5</td><td style="text-align:right;">PASS</td></tr><tr><td>C14</td><td>Terminal-history preservation</td><td style="text-align:right;">5</td><td style="text-align:right;">PASS</td></tr></tbody></table><p>The 71 recorded assertions were recomputed during publication review. All manifest digests, actual-result digests, input-bundle digest, and the aggregate conformance-result digest matched the package records.</p><h1 id="_6-s0-6-to-s1-0-engineering-delta" tabindex="-1">6. S0.6 to S1.0 Engineering Delta <a class="header-anchor" href="#_6-s0-6-to-s1-0-engineering-delta" aria-label="Permalink to &quot;6. S0.6 to S1.0 Engineering Delta&quot;">​</a></h1><h2 id="_6-1-stable-machine-identity" tabindex="-1">6.1 Stable machine identity <a class="header-anchor" href="#_6-1-stable-machine-identity" aria-label="Permalink to &quot;6.1 Stable machine identity&quot;">​</a></h2><p>S1.0 reissues the reviewed S0.6 behavior under stable S1.0 schema identifiers, Profile identities, canonicalization identity, and executable corpus paths. CodeFlowMu V1.8.0 binds its validator and Reader to those identities rather than treating an older-Core result as evidence for S1.0.</p><h2 id="_6-2-product-level-projection" tabindex="-1">6.2 Product-level projection <a class="header-anchor" href="#_6-2-product-level-projection" aria-label="Permalink to &quot;6.2 Product-level projection&quot;">​</a></h2><p>The product runner imports the exact S1.0 bundle, validates the lifecycle Profile through the CodeFlowMu protocol surface, creates the CodeFlowMu <code>GovernanceReader</code>, and passes FCoP-derived source candidates through the product path. The Reference Reader module is retained in the bundle for traceability but is not imported or called by the product runner.</p><h2 id="_6-3-regression-alignment-without-criterion-weakening" tabindex="-1">6.3 Regression alignment without criterion weakening <a class="header-anchor" href="#_6-3-regression-alignment-without-criterion-weakening" aria-label="Permalink to &quot;6.3 Regression alignment without criterion weakening&quot;">​</a></h2><p>The retained pre-fix Runtime run reported 1,520 passed, 2 failed, and 1 skipped. The failures were stale expectations for V1.7 wording and for the distinction between QA execution completion and a failing business verdict. Tests were aligned to the already implemented contract; no S1.0 schema, fixture, mandatory assertion, Reader behavior, or pass criterion was weakened.</p><p>A later isolated wake-endpoint failure passed five immediate repetitions. One full run also stalled in <code>TaskDispatcher.test.ts</code>; the exact child process was terminated, and a bounded audit then reported 29 passed / 0 failed. These records remain in the package rather than being erased.</p><h1 id="_7-regression-and-reproducer-results" tabindex="-1">7. Regression and Reproducer Results <a class="header-anchor" href="#_7-regression-and-reproducer-results" aria-label="Permalink to &quot;7. Regression and Reproducer Results&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Surface</th><th style="text-align:right;">Final result</th><th>Interpretation</th></tr></thead><tbody><tr><td>CodeFlowMu TMPA Runtime suite</td><td style="text-align:right;">24 passed / 0 failed</td><td>Product Reader unit and integration surface</td></tr><tr><td>CodeFlowMu Runtime full suite</td><td style="text-align:right;">1,522 passed / 0 failed / 1 skipped</td><td>Final full run</td></tr><tr><td>Runtime batched coverage</td><td style="text-align:right;">207/207 files; 1,522 passed / 0 failed / 1 skipped</td><td>Exact file coverage confirmation</td></tr><tr><td>CodeFlowMu Shell batched coverage</td><td style="text-align:right;">791 passed / 0 failed</td><td>Exact 8-batch execution</td></tr><tr><td>Protocol validation and typecheck</td><td style="text-align:right;">exit 0</td><td>Schema and validator surface</td></tr><tr><td>FCoP locked reference implementation</td><td style="text-align:right;">1,210 passed / 2 skipped</td><td>Dependency regression; not a substitute for product Reader</td></tr><tr><td>Reduced clean-machine reproducer</td><td style="text-align:right;">14/14 PASS</td><td><code>npm ci</code> plus exact S1.0 product runner</td></tr></tbody></table><p>The reproducer initially excluded an entire Protocol schemas directory and therefore also removed the required S1.0 schemas. That reduced-scope attempt is retained as a failure. The corrected reproducer excludes only unrelated legacy material, retains <code>schemas/tmpa</code>, installs from the lock file, and executes the same product runner successfully.</p><h1 id="_8-retained-wp-13-evidence-gating-case" tabindex="-1">8. Retained WP-13 Evidence-Gating Case <a class="header-anchor" href="#_8-retained-wp-13-evidence-gating-case" aria-label="Permalink to &quot;8. Retained WP-13 Evidence-Gating Case&quot;">​</a></h1><p>WP-13 is retained as a field-oriented example of multi-agent fact checking with executor/reviewer separation, evidence admission, audit records, and explicit lifecycle boundaries. Its evidence package supports the bounded conclusion that development completed and role-separated QA passed for the captured task state. It also records that later task snapshots were still <code>review</code> and <code>pending</code>, that a scheduled date was advanced without a separately located approval artifact, and that runtime binding and signed checksums were outside the package boundary.</p><p>WP-13 illustrates why TMPA separates execution evidence, review evidence, authorization, lifecycle state, and publication claims. It is not one of the S1.0 C01–C14 product fixtures. It does not prove the theory, independently validate CodeFlowMu, or prove that multi-agent systems cannot hallucinate.</p>`,21)])])}const g=e(r,[["render",n]]);export{u as __pageData,g as default};
